// === Tab: mySketch ===
let xmin = -0.25
let xmax = 4.25
let ymin = -0.25
let ymax = 1.25
let points = [];
let nPoints = 10000;
let iteratePoints = true;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(100);

	// initialize random points
	for (let i = 0; i < nPoints; i++) {
		let px = map(Math.random(), 0, 1, max(0, xmin), min(4, xmax));
		let py = map(Math.random(), 0, 1, max(0, ymin), min(1, ymax));
		points.push(createVector(px, py));
	}
}

function draw() {
	background(100);

	noStroke();
	for (let i = 0; i < nPoints; i++) {
		// draw points to screen
		let pxScreen = map(points[i].x, xmin, xmax, 0, windowWidth);
		let pyScreen = map(points[i].y, ymin, ymax, windowHeight, 0);
		ellipse(pxScreen, pyScreen, 1, 1);
		//update points after iteration
		if (iteratePoints){
			points[i] = logisticMap(points[i]);
		}
	}
}

function logisticMap(point) {
	let r = point.x;
	let y = point.y;
	let newy = r * y * (1-y);
	return createVector(r, newy);
}

function mousePressed() {
	iteratePoints = !iteratePoints;
}

